"use client";

import { useState, useEffect, useMemo, useCallback } from "react";
import { showToast } from "@/components/ToastNotification";
import {
  Box,
  Button,
  Chip,
  Collapse,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  IconButton,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TableSortLabel,
  TextField,
} from "@mui/material";
import { HelpOutline, MoreVert, TrendingUp } from "@mui/icons-material";
import {
  getIncomeListAction,
  createIncomeAction,
  updateIncomeAction,
  deleteIncomeAction,
} from "@/features/income/actions";
import { getAccountsAction } from "@/features/account/actions";
import { getEnumsAction } from "@/features/enum/actions";
import {
  cellSx,
  headCellSx,
  inputSx,
  formatIDR,
  sortLabelSx,
  tableRowSx,
  tablePaperSx,
  popperStyles,
  dialogPaperSx,
  dialogTitleSx,
  dialogContentSx,
  dialogActionsSx,
  cancelBtnSx,
  saveBtnSx,
} from "@/lib/theme-shared";
import TableFilter from "@/components/TableFilter";
import PageHeader from "@/components/PageHeader";
import SummaryCards from "@/components/SummaryCards";
import DataTableToolbar from "@/components/DataTableToolbar";
import ActionMenu from "@/components/ActionMenu";
import ConfirmDeleteDialog from "@/components/ConfirmDeleteDialog";
import StyledTablePagination from "@/components/StyledTablePagination";
import TableSkeletonRows from "@/components/TableSkeletonRows";
import EmptyTableRow from "@/components/EmptyTableRow";
import { useDataRefresh } from "@/hooks/useDataRefresh";
import { useQueryParams, readQueryParams } from "@/hooks/useQueryParams";
import { LocalizationProvider } from "@mui/x-date-pickers/LocalizationProvider";
import { AdapterDateFns } from "@mui/x-date-pickers/AdapterDateFns";
import { DatePicker } from "@mui/x-date-pickers/DatePicker";
import { parseISO, format } from "date-fns";
import type { IncomeRow } from "@/types/transaction.type";
import TutorialTour from "@/components/TutorialTour";
import { tourSteps } from "./tourSteps";

// ─── Helpers ─────────────────────────────────────────────────────────────────
const jenisColor: Record<string, "success" | "info" | "warning" | "default"> = {
  Salary: "success",
  Allowance: "info",
  Bonus: "warning",
  Gaji: "success",
  Tunjangan: "info",
  Aktif: "success",
  Pasif: "info",
  Lainnya: "default",
};

const COLUMNS = [
  { id: "id" as const, label: "ID" },
  { id: "tanggal" as const, label: "Tanggal" },
  { id: "jenis" as const, label: "Jenis" },
  { id: "sumber" as const, label: "Sumber" },
  { id: "akun" as const, label: "Akun" },
  { id: "nominal" as const, label: "Nominal" },
  { id: "catatan" as const, label: "Catatan" },
];

const SKELETON_WIDTHS = [50, 80, 70, 70, 70, 60, 100, 40];

// ─── Component ────────────────────────────────────────────────────────────────
export default function IncomePage() {
  const [rows, setRows] = useState<IncomeRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [tourActive, setTourActive] = useState(false);

  const [accounts, setAccounts] = useState<{ id: number; name: string }[]>([]);
  const [types, setTypes] = useState<{ id: number; value: string }[]>([]);
  const [sources, setSources] = useState<{ id: number; value: string }[]>([]);

  const accountMap = useMemo(() => Object.fromEntries(accounts.map((a) => [a.id, a.name])), [accounts]);
  const typeMap = useMemo(() => Object.fromEntries(types.map((t) => [t.id, t.value])), [types]);
  const sourceMap = useMemo(() => Object.fromEntries(sources.map((s) => [s.id, s.value])), [sources]);

  const [search, setSearch] = useState("");
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [orderBy, setOrderBy] = useState<keyof IncomeRow>("tanggal");
  const [order, setOrder] = useState<"asc" | "desc">("desc");
  const [actionAnchor, setActionAnchor] = useState<{ el: HTMLElement; row: IncomeRow } | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [rowToDelete, setRowToDelete] = useState<IncomeRow | null>(null);
  const [formOpen, setFormOpen] = useState(false);
  const [editRow, setEditRow] = useState<IncomeRow | null>(null);

  const [activeFilters, setActiveFilters] = useState<Record<string, string | number>>({
    accountId: "",
    typeId: "",
    sourceId: "",
  });
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [filterOpen, setFilterOpen] = useState(false);

  const [form, setForm] = useState<any>({
    tanggal: new Date().toISOString().split("T")[0],
    typeId: 0,
    sourceId: 0,
    accountId: 0,
    amount: "",
    note: "",
  });

  // ─── Data Loading ─────────────────────────────────────────────────────────
  const loadData = useCallback(async () => {
    try {
      setLoading(true);
      const [accRes, typeRes, srcRes, rowsRes] = await Promise.all([
        getAccountsAction(),
        getEnumsAction('income_type'),
        getEnumsAction('income_source'),
        getIncomeListAction({ page: 1, pageSize: 100 }),
      ]);

      let currentAccounts: any[] = [];
      let currentTypes: any[] = [];
      let currentSources: any[] = [];

      if (accRes.success) { setAccounts(accRes.data as any[]); currentAccounts = accRes.data; }
      if (typeRes.success) { setTypes(typeRes.data as any[]); currentTypes = typeRes.data; }
      if (srcRes.success) { setSources(srcRes.data as any[]); currentSources = srcRes.data; }

      const currentAccountMap = Object.fromEntries(currentAccounts.map((a: any) => [a.id, a.name]));
      const currentTypeMap = Object.fromEntries(currentTypes.map((t: any) => [t.id, t.value]));
      const currentSourceMap = Object.fromEntries(currentSources.map((s: any) => [s.id, s.value]));

      if (rowsRes.success) {
        const items = rowsRes.data.items as any[];
        setRows(
          items.map((inc) => ({
            id: `INC-${String(inc.id).padStart(3, '0')}`,
            tanggal: inc.date,
            jenis: currentTypeMap[inc.typeId] || '',
            sumber: currentSourceMap[inc.sourceId] || '',
            akun: currentAccountMap[inc.accountId] || '',
            nominal: Number(inc.amount) || 0,
            catatan: inc.note || '',
            raw: inc,
          }))
        );
      }
    } catch (err) {
      console.error('failed to load initial data', err);
    } finally {
      setLoading(false);
    }
  }, []);

  const loadRows = useCallback(async () => {
    try {
      setLoading(true);
      const json = await getIncomeListAction({ page: 1, pageSize: 100 });
      if (json.success) {
        const items = json.data.items as any[];
        setRows(
          items.map((inc) => ({
            id: `INC-${String(inc.id).padStart(3, '0')}`,
            tanggal: inc.date,
            jenis: typeMap[inc.typeId] || '',
            sumber: sourceMap[inc.sourceId] || '',
            akun: accountMap[inc.accountId] || '',
            nominal: Number(inc.amount) || 0,
            catatan: inc.note || '',
            raw: inc,
          }))
        );
      }
    } catch (err) {
      console.error('failed to load incomes', err);
    } finally {
      setLoading(false);
    }
  }, [typeMap, sourceMap, accountMap]);

  useEffect(() => { loadData(); }, [loadData]);
  useDataRefresh(loadData);

  // ─── URL Sync ─────────────────────────────────────────────────────────────
  useEffect(() => {
    if (typeof window === "undefined") return;
    const params = readQueryParams();
    const urlSearch = params.get("search") || "";
    const urlAccountId = params.get("accountId") ? Number(params.get("accountId")) || params.get("accountId")! : "";
    const urlTypeId = params.get("typeId") ? Number(params.get("typeId")) || params.get("typeId")! : "";
    const urlSourceId = params.get("sourceId") ? Number(params.get("sourceId")) || params.get("sourceId")! : "";
    const urlStartDate = params.get("startDate") || "";
    const urlEndDate = params.get("endDate") || "";

    if (urlSearch) setSearch(urlSearch);
    if (urlAccountId || urlTypeId || urlSourceId) {
      setActiveFilters({ accountId: urlAccountId, typeId: urlTypeId, sourceId: urlSourceId });
      setFilterOpen(true);
    }
    if (urlStartDate) { setStartDate(urlStartDate); setFilterOpen(true); }
    if (urlEndDate) { setEndDate(urlEndDate); setFilterOpen(true); }
  }, []);

  useQueryParams({
    search,
    ...(activeFilters.accountId ? { accountId: String(activeFilters.accountId) } : {}),
    ...(activeFilters.typeId ? { typeId: String(activeFilters.typeId) } : {}),
    ...(activeFilters.sourceId ? { sourceId: String(activeFilters.sourceId) } : {}),
    ...(startDate ? { startDate } : {}),
    ...(endDate ? { endDate } : {}),
  });

  // ─── Filtering & Sorting ─────────────────────────────────────────────────
  const filtered = rows
    .filter((r) => {
      const q = search.toLowerCase();
      const matchesSearch =
        r.id.toLowerCase().includes(q) ||
        r.sumber.toLowerCase().includes(q) ||
        r.jenis.toLowerCase().includes(q) ||
        r.akun.toLowerCase().includes(q) ||
        r.catatan.toLowerCase().includes(q);
      if (!matchesSearch) return false;
      if (activeFilters.accountId && r.raw?.accountId !== activeFilters.accountId) return false;
      if (activeFilters.typeId && r.raw?.typeId !== activeFilters.typeId) return false;
      if (activeFilters.sourceId && r.raw?.sourceId !== activeFilters.sourceId) return false;
      if (startDate && new Date(r.tanggal) < new Date(startDate)) return false;
      if (endDate && new Date(r.tanggal) > new Date(endDate)) return false;
      return true;
    })
    .sort((a, b) => {
      const av = a[orderBy];
      const bv = b[orderBy];
      if (av < bv) return order === "asc" ? -1 : 1;
      if (av > bv) return order === "asc" ? 1 : -1;
      return 0;
    });

  const paginated = filtered.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage);
  const totalNominal = filtered.reduce((s, r) => s + r.nominal, 0);

  const handleSort = (col: keyof IncomeRow) => {
    if (orderBy === col) setOrder(order === "asc" ? "desc" : "asc");
    else { setOrderBy(col); setOrder("asc"); }
    setPage(0);
  };

  // ─── CRUD Handlers ────────────────────────────────────────────────────────
  const handleDelete = async () => {
    if (!rowToDelete) return;
    try {
      const idNum = parseInt(rowToDelete.id.replace(/^INC-/, ''), 10);
      await deleteIncomeAction(idNum);
      showToast("Data pemasukan berhasil dihapus!", "success");
      loadRows();
    } catch (err) {
      console.error('delete error', err);
      showToast("Gagal menghapus data pemasukan.", "error");
    }
    setDeleteDialogOpen(false);
    setActionAnchor(null);
  };

  const openAdd = () => {
    setEditRow(null);
    setForm({
      tanggal: new Date().toISOString().split("T")[0],
      typeId: types[0]?.id || 0,
      sourceId: sources[0]?.id || 0,
      accountId: accounts[0]?.id || 0,
      amount: "",
      note: "",
    });
    setFormOpen(true);
  };

  const openEdit = (row: IncomeRow) => {
    setEditRow(row);
    const raw = (row as any).raw;
    setForm({
      tanggal: raw.date,
      typeId: raw.typeId,
      sourceId: raw.sourceId,
      accountId: raw.accountId,
      amount: String(raw.amount),
      note: raw.note || "",
    });
    setFormOpen(true);
    setActionAnchor(null);
  };

  const handleSave = async () => {
    if (!form.amount) return;
    try {
      if (editRow) {
        const idNum = parseInt(editRow.id.replace(/^INC-/, ''), 10);
        await updateIncomeAction({ id: idNum, ...form, date: form.tanggal });
        showToast("Pemasukan berhasil diperbarui!", "success");
      } else {
        await createIncomeAction({
          date: form.tanggal,
          typeId: form.typeId,
          sourceId: form.sourceId,
          accountId: form.accountId,
          amount: Number(form.amount),
          note: form.note,
        });
        showToast("Pemasukan berhasil ditambahkan!", "success");
      }
      await loadRows();
    } catch (err) {
      console.error('save error', err);
      showToast("Gagal menyimpan data pemasukan.", "error");
    }
    setFormOpen(false);
  };

  // ─── Computed Summary ─────────────────────────────────────────────────────
  const totalThisMonth = rows
    .filter((r) => r.tanggal.startsWith("2025-03"))
    .reduce((s, r) => s + r.nominal, 0);
  const avgIncome = rows.length > 0 ? rows.reduce((s, r) => s + r.nominal, 0) / rows.length : 0;

  const hasActiveFilters = Object.values(activeFilters).some((v) => v !== "") || !!startDate || !!endDate;

  // ─── Render ───────────────────────────────────────────────────────────────
  return (
    <Box sx={{ p: { xs: 3, md: 4 }, minHeight: "100vh" }}>
      <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }} id="tour-page-header">
        <PageHeader
          title="Income"
          subtitle="Kelola dan pantau seluruh data pemasukan"
          icon={<TrendingUp sx={{ fontSize: 18, color: "#22c55e" }} />}
          iconBgColor="rgba(34,197,94,0.12)"
        />
        <Button
          variant="outlined"
          onClick={() => setTourActive(true)}
          startIcon={<HelpOutline sx={{ fontSize: 16 }} />}
          sx={{
            mt: 1,
            color: "#818cf8",
            borderColor: "rgba(129, 140, 248, 0.3)",
            fontWeight: 600,
            fontSize: "0.75rem",
            px: 2,
            py: 0.75,
            borderRadius: "10px",
            textTransform: "none",
            backgroundColor: "rgba(129, 140, 248, 0.03)",
            "&:hover": {
              borderColor: "#818cf8",
              backgroundColor: "rgba(129, 140, 248, 0.08)",
            },
          }}
        >
          Lihat Tutorial
        </Button>
      </Box>

      <Box id="tour-summary-cards">
        <SummaryCards
          cards={[
            { label: "Total Pemasukan", value: formatIDR(rows.reduce((s, r) => s + r.nominal, 0)), sub: `${rows.length} transaksi` },
            { label: "Bulan Ini (Mar)", value: formatIDR(totalThisMonth), sub: "Maret 2025" },
            { label: "Rata-rata Transaksi", value: formatIDR(avgIncome), sub: "Per transaksi" },
          ]}
        />
      </Box>

      <Paper elevation={0} sx={tablePaperSx}>
        <DataTableToolbar
          search={search}
          onSearchChange={(v) => { setSearch(v); setPage(0); }}
          resultCount={filtered.length}
          resultTotal={formatIDR(totalNominal)}
          filterOpen={filterOpen}
          onFilterToggle={() => setFilterOpen(!filterOpen)}
          onResetFilters={() => { setActiveFilters({ accountId: "", typeId: "", sourceId: "" }); setStartDate(""); setEndDate(""); }}
          hasActiveFilters={hasActiveFilters}
          onAdd={openAdd}
        />

        <Collapse in={filterOpen}>
          <Box sx={{ px: 3, pb: 2 }}>
            <TableFilter
              options={[
                { key: "accountId", label: "Akun", options: accounts.map((a) => ({ id: a.id, name: a.name })) },
                { key: "typeId", label: "Jenis", options: types.map((t) => ({ id: t.id, name: t.value })) },
                { key: "sourceId", label: "Sumber", options: sources.map((s) => ({ id: s.id, name: s.value })) },
              ]}
              activeFilters={activeFilters}
              onFilterChange={(key, val) => setActiveFilters((prev) => ({ ...prev, [key]: val }))}
              startDate={startDate}
              endDate={endDate}
              onStartDateChange={setStartDate}
              onEndDateChange={setEndDate}
            />
          </Box>
        </Collapse>

        {/* Table */}
        <TableContainer id="tour-table-container">
          <Table size="small" sx={{ tableLayout: "auto" }}>
            <TableHead>
              <TableRow>
                {COLUMNS.map((col) => (
                  <TableCell key={col.id} sx={headCellSx}>
                    <TableSortLabel
                      active={orderBy === col.id}
                      direction={orderBy === col.id ? order : "asc"}
                      onClick={() => handleSort(col.id)}
                      sx={sortLabelSx}
                    >
                      {col.label}
                    </TableSortLabel>
                  </TableCell>
                ))}
                <TableCell sx={{ ...headCellSx, textAlign: "center" }}>Aksi</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {loading ? (
                <TableSkeletonRows columns={SKELETON_WIDTHS} />
              ) : paginated.length === 0 ? (
                <EmptyTableRow colSpan={8} />
              ) : (
                paginated.map((row, i) => (
                  <TableRow key={row.id} sx={tableRowSx(i)}>
                    <TableCell sx={{ ...cellSx, color: "#6366f1", fontWeight: 600, fontFamily: "monospace", fontSize: "0.75rem" }}>
                      {row.id}
                    </TableCell>
                    <TableCell sx={cellSx}>
                      {new Date(row.tanggal).toLocaleDateString("id-ID", { day: "2-digit", month: "short", year: "numeric" })}
                    </TableCell>
                    <TableCell sx={cellSx}>
                      <Chip
                        label={row.jenis}
                        size="small"
                        color={jenisColor[row.jenis] ?? "default"}
                        variant="outlined"
                        sx={{
                          fontSize: "0.6875rem", height: 22, fontWeight: 600, borderRadius: "6px",
                          color: (jenisColor[row.jenis] && jenisColor[row.jenis] !== "default") ? undefined : "#cbd5e1",
                          borderColor: (jenisColor[row.jenis] && jenisColor[row.jenis] !== "default") ? undefined : "rgba(255,255,255,0.15)",
                        }}
                      />
                    </TableCell>
                    <TableCell sx={{ ...cellSx, maxWidth: 160, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                      {row.sumber}
                    </TableCell>
                    <TableCell sx={cellSx}>
                      <Chip label={row.akun} size="small" variant="filled" sx={{ fontSize: "0.6875rem", height: 22, fontWeight: 500, borderRadius: "6px", backgroundColor: "rgba(71,85,105,0.4)", color: "#94a3b8" }} />
                    </TableCell>
                    <TableCell sx={{ ...cellSx, color: "#22c55e", fontWeight: 600, whiteSpace: "nowrap" }}>
                      {formatIDR(row.nominal)}
                    </TableCell>
                    <TableCell sx={{ ...cellSx, color: "#64748b", maxWidth: 200, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                      {row.catatan || "—"}
                    </TableCell>
                    <TableCell sx={{ ...cellSx, textAlign: "center" }}>
                      <IconButton
                        size="small"
                        onClick={(e) => setActionAnchor({ el: e.currentTarget, row })}
                        sx={{ color: "#475569", "&:hover": { color: "#c7d2fe", bgcolor: "rgba(99,102,241,0.1)" } }}
                      >
                        <MoreVert fontSize="small" />
                      </IconButton>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </TableContainer>

        <StyledTablePagination
          count={filtered.length}
          page={page}
          rowsPerPage={rowsPerPage}
          onPageChange={(_, p) => setPage(p)}
          onRowsPerPageChange={(e) => { setRowsPerPage(parseInt(e.target.value, 10)); setPage(0); }}
        />
      </Paper>

      {/* Row Action Menu */}
      <ActionMenu
        anchorEl={actionAnchor?.el ?? null}
        open={Boolean(actionAnchor)}
        onClose={() => setActionAnchor(null)}
        onEdit={() => { if (actionAnchor) openEdit(actionAnchor.row); }}
        onDelete={() => { if (actionAnchor) { setRowToDelete(actionAnchor.row); setDeleteDialogOpen(true); } }}
      />

      {/* Add/Edit Dialog */}
      <Dialog open={formOpen} onClose={() => setFormOpen(false)} PaperProps={dialogPaperSx}>
        <DialogTitle sx={dialogTitleSx}>
          {editRow ? "Edit Pemasukan" : "Tambah Pemasukan"}
        </DialogTitle>
        <DialogContent sx={dialogContentSx}>
          <LocalizationProvider dateAdapter={AdapterDateFns}>
            <DatePicker
              label="Tanggal"
              value={form.tanggal ? parseISO(form.tanggal) : null}
              onChange={(newVal) => { if (newVal) setForm({ ...form, tanggal: format(newVal as Date, "yyyy-MM-dd") }); }}
              slotProps={{
                textField: { size: "small", fullWidth: true },
                popper: { sx: popperStyles },
              }}
            />
          </LocalizationProvider>

          <FormControl size="small" fullWidth>
            <InputLabel sx={{ color: "#64748b" }}>Jenis</InputLabel>
            <Select value={form.typeId} label="Jenis" onChange={(e) => setForm({ ...form, typeId: Number(e.target.value) })} sx={inputSx}>
              {types.map((t) => <MenuItem key={t.id} value={t.id}>{t.value}</MenuItem>)}
            </Select>
          </FormControl>

          <FormControl size="small" fullWidth>
            <InputLabel sx={{ color: "#64748b" }}>Sumber</InputLabel>
            <Select value={form.sourceId} label="Sumber" onChange={(e) => setForm({ ...form, sourceId: Number(e.target.value) })} sx={inputSx}>
              {sources.map((s) => <MenuItem key={s.id} value={s.id}>{s.value}</MenuItem>)}
            </Select>
          </FormControl>

          <FormControl size="small" fullWidth>
            <InputLabel sx={{ color: "#64748b" }}>Akun</InputLabel>
            <Select value={form.accountId} label="Akun" onChange={(e) => setForm({ ...form, accountId: Number(e.target.value) })} sx={inputSx}>
              {accounts.map((a) => <MenuItem key={a.id} value={a.id}>{a.name}</MenuItem>)}
            </Select>
          </FormControl>

          <TextField label="Nominal (IDR)" size="small" fullWidth type="number" value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })} InputLabelProps={{ sx: { color: "#64748b" } }} InputProps={{ sx: inputSx }} />
          <TextField label="Catatan" size="small" fullWidth multiline rows={2} value={form.note} onChange={(e) => setForm({ ...form, note: e.target.value })} InputLabelProps={{ sx: { color: "#64748b" } }} InputProps={{ sx: inputSx }} />
        </DialogContent>
        <DialogActions sx={dialogActionsSx}>
          <Button onClick={() => setFormOpen(false)} size="small" sx={cancelBtnSx}>Batal</Button>
          <Button onClick={handleSave} size="small" variant="contained" sx={saveBtnSx}>{editRow ? "Simpan" : "Tambah"}</Button>
        </DialogActions>
      </Dialog>

      {/* Delete Confirm */}
      <ConfirmDeleteDialog
        open={deleteDialogOpen}
        title="Hapus Pemasukan"
        onClose={() => { setDeleteDialogOpen(false); setRowToDelete(null); }}
        onConfirm={handleDelete}
        itemId={rowToDelete?.id}
      />

      <TutorialTour
        steps={tourSteps}
        active={tourActive}
        onClose={() => setTourActive(false)}
      />
    </Box>
  );
}